"""Simulate a small Nanopore WGS dataset with known mitochondrial reads.

The simulated genome is designed to be *hard* for MITNANEX, not trivial:

* nuclear chromosome generated by a 2nd-order Markov chain (GC ~40%);
* an rDNA-like tandem array (high copy number, GC-rich) and a dispersed
  transposon family - both create high-coverage nuclear read clusters that
  compete with the mitochondrion in the coverage filter;
* a NUMT (a piece of the mitogenome inserted in the nucleus);
* the real human mitogenome (rCRS, circular) at high copy number.

Every read name starts with its origin (``mt``, ``nuc``, ``rdna``, ``te``,
``numt``) so that the extraction can be evaluated afterwards.

Usage:
    python tests/simulate.py --out reads.fastq [--seed 1]
"""

from __future__ import annotations

import argparse
from pathlib import Path

import numpy as np
import pandas as pd

BASES = np.array(list("ACGT"))
REPO = Path(__file__).resolve().parents[1]
MITO_FASTA = REPO / "mitnanex" / "data" / "refseqMT" / "chrMT.fna"


def markov_sequence(rng: np.random.Generator, length: int, gc: float, concentration: float = 3.0) -> np.ndarray:
    """Random sequence (as codes 0-3) from a random 2nd-order Markov chain.

    Each of the 16 dinucleotide contexts gets its own next-base distribution
    drawn from a Dirichlet centred on the target GC content, which gives the
    sequence a characteristic trinucleotide composition.
    """
    base_probs = np.array([(1 - gc) / 2, gc / 2, gc / 2, (1 - gc) / 2])
    transitions = rng.dirichlet(base_probs * concentration * 4, size=16)
    seq = np.empty(length, dtype=np.int8)
    seq[:2] = rng.choice(4, size=2, p=base_probs)
    uniform = rng.random(length)
    cumulative = transitions.cumsum(axis=1)
    for i in range(2, length):  # sequential by nature; only done once per genome
        seq[i] = np.searchsorted(cumulative[seq[i - 2] * 4 + seq[i - 1]], uniform[i])
    return np.minimum(seq, 3)


def mutate(rng: np.random.Generator, seq: np.ndarray, rate: float) -> np.ndarray:
    """Copy of ``seq`` with a fraction ``rate`` of substitutions (repeat divergence)."""
    out = seq.copy()
    hits = rng.random(len(seq)) < rate
    out[hits] = (out[hits] + rng.integers(1, 4, hits.sum())) % 4
    return out


def add_sequencing_errors(rng: np.random.Generator, seq: np.ndarray, sub: float, ins: float, dele: float) -> np.ndarray:
    """Nanopore-like errors: substitutions, insertions and deletions."""
    r = rng.random(len(seq))
    out = seq.copy()
    subs = r < sub
    out[subs] = (out[subs] + rng.integers(1, 4, subs.sum())) % 4
    # Each base is emitted 0 (deleted), 1, or 2 (followed by an insertion) times.
    copies = np.ones(len(seq), dtype=np.int64)
    copies[(r >= sub) & (r < sub + dele)] = 0
    copies[(r >= sub + dele) & (r < sub + dele + ins)] = 2
    out = np.repeat(out, copies)
    inserted = np.zeros(len(out), dtype=bool)
    inserted[np.cumsum(copies)[copies == 2] - 1] = True  # second copy is the inserted base
    out[inserted] = rng.integers(0, 4, inserted.sum())
    return out


def build_genome(rng: np.random.Generator, nuclear_len: int, mito: np.ndarray):
    """Nuclear chromosome with repeats + per-base origin labels."""
    nuclear = markov_sequence(rng, nuclear_len, gc=0.40)
    origin = np.zeros(nuclear_len, dtype=np.int8)  # 0 nuc, 1 rdna, 2 te, 3 numt

    # rDNA-like tandem array: 40 copies of a 9 kb GC-rich unit (~1% divergence).
    rdna_unit = markov_sequence(rng, 9_000, gc=0.55)
    rdna = np.concatenate([mutate(rng, rdna_unit, 0.01) for _ in range(40)])
    # Transposon family: 6 kb element, 60 copies with 3% divergence, dispersed.
    te_unit = markov_sequence(rng, 6_000, gc=0.38)
    # NUMT: 5 kb of the mitogenome with 2% divergence.
    numt = mutate(rng, mito[3_000:8_000], 0.02)

    pieces, labels, cursor = [], [], 0
    insert_points = np.sort(rng.choice(np.arange(10_000, nuclear_len - 10_000), size=62, replace=False))
    inserts = [(rdna, 1)] + [(mutate(rng, te_unit, 0.03), 2) for _ in range(60)] + [(numt, 3)]
    for point, (seq, label) in zip(insert_points, rng.permutation(np.array(inserts, dtype=object))):
        pieces += [nuclear[cursor:point], seq]
        labels += [origin[cursor:point], np.full(len(seq), label, dtype=np.int8)]
        cursor = point
    pieces.append(nuclear[cursor:])
    labels.append(origin[cursor:])
    return np.concatenate(pieces), np.concatenate(labels)


def sample_reads(rng, genome, labels, depth, circular, names, error_rate=0.02, read_len_median=6_000):
    """Sample error-containing reads; returns a DataFrame (id, seq, qual)."""
    genome_len = len(genome)
    n_reads = int(depth * genome_len / (read_len_median * 1.3))
    lengths = rng.lognormal(np.log(read_len_median), 0.6, n_reads).astype(int).clip(500, 60_000)
    if circular:
        lengths = lengths.clip(max=genome_len - 100)
    starts = rng.integers(0, genome_len if circular else genome_len - lengths.min(), n_reads)
    doubled = np.concatenate([genome, genome]) if circular else genome
    doubled_labels = np.concatenate([labels, labels]) if circular else labels

    records = []
    for i, (start, length) in enumerate(zip(starts, lengths)):
        end = min(start + length, len(doubled))
        fragment = doubled[start:end]
        origin = names[np.bincount(doubled_labels[start:end], minlength=len(names)).argmax()]
        if rng.random() < 0.5:  # reverse strand
            fragment = (3 - fragment)[::-1]
        # Split the total error rate as typically seen in Nanopore data.
        read = add_sequencing_errors(rng, fragment, sub=0.35 * error_rate, ins=0.25 * error_rate, dele=0.40 * error_rate)
        qual = np.full(len(read), "5")
        records.append((f"{origin}_{'c' if circular else 'n'}{i}", "".join(BASES[read]), "".join(qual)))
    return pd.DataFrame(records, columns=["id", "seq", "qual"])


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--out", required=True, type=Path)
    parser.add_argument("--nuclear-len", type=int, default=4_000_000)
    parser.add_argument("--nuclear-depth", type=float, default=12)
    parser.add_argument("--mito-depth", type=float, default=150)
    parser.add_argument("--error-rate", type=float, default=0.02, help="per-base error rate (R10.4.1 ~0.02)")
    parser.add_argument("--seed", type=int, default=1)
    args = parser.parse_args()

    rng = np.random.default_rng(args.seed)
    mito_text = "".join(MITO_FASTA.read_text().splitlines()[1:]).upper()
    mito = np.array(["ACGT".index(b) for b in mito_text if b in "ACGT"], dtype=np.int8)

    nuclear, nuclear_labels = build_genome(rng, args.nuclear_len, mito)
    nuc_reads = sample_reads(rng, nuclear, nuclear_labels, args.nuclear_depth, False, ["nuc", "rdna", "te", "numt"], args.error_rate)
    mt_reads = sample_reads(rng, mito, np.zeros(len(mito), dtype=np.int8), args.mito_depth, True, ["mt"], args.error_rate)

    reads = pd.concat([nuc_reads, mt_reads]).sample(frac=1, random_state=args.seed)
    text = ("@" + reads["id"] + "\n" + reads["seq"] + "\n+\n" + reads["qual"]).str.cat(sep="\n")
    args.out.write_text(text + "\n")
    print(reads["id"].str.split("_").str[0].value_counts().to_string())


if __name__ == "__main__":
    main()
